        int n = sc.nextInt();
        String s = sc.next();
        char[] arr = s.toCharArray();
        solve(arr, 0);
        System.out.println(maxRemovals);
    }

    static void solve(char[] arr, int removed) {
        maxRemovals = Math.max(maxRemovals, removed);
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == 0) continue;
            char c = arr[i];
            if (c == 'a') continue;
            char prev = (char)(c - 1);
            boolean canRemove = false;
            if (i > 0 && arr[i-1] == prev) canRemove = true;
            if (i < arr.length - 1 && arr[i+1] == prev) canRemove = true;
            if (canRemove) {
                char temp = arr[i];
                arr[i] = 0;
                solve(arr, removed + 1);
                arr[i] = temp;
            }
        }
    }
}
